(window.MATRIX_DATA_PARTS ||= Object.create(null))["data/glyphs-0022.js"] = [{"id":"glyph-seal-6d4d","script":"seal","character":"浍","reading":"huì","description":"河名,浍河","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-浍"},{"id":"glyph-seal-6d4e","script":"seal","character":"济","reading":"jì","description":"发源于今河南省济源县西王屋山,原在山东境内与黄河并行入渤海◇因黄河改道,下游被黄河淹没。现在黄河下游的河道就是原来济水的河道\n州名\n五代周置,在今山东省巨野县\n金置,在今吉林省农安县\n众多\n⒈济水，〈古〉水名。发源于河南省，流经山东省入渤海。今黄河下流河道即原济水河道。\n⒉济南市，济宁市，均在山东省。\n⒈渡，过河同船～水。同舟共～。\n⒉帮助，援救接～。救～。～穷扶贫。\n⒊有利，补益万民以～。\n⒋成夫～大事必以人为本。\n济qí 1.庄敬。 2.整治，使整齐。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-济"},{"id":"glyph-seal-6d4f","script":"seal","character":"浏","reading":"liú","description":"通漻”。水深而清澈\n风疾速的样子\n风轻吹的样子\n⒈水流清亮的样子。\n⒉风刮得紧的样子。\n浏liū 1.溜。偷偷地走开。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-浏"},{"id":"glyph-seal-6d51","script":"seal","character":"浑","reading":"hún","description":"河名\n桑干河上游支流,亦名浑源川,发源于山西省北端西麓\n卢沟河在元明后的别称,因河水浑浊得名,即今永定河\n小辽河,辽河最大的支流\n浑江,又名佟家江,发源于吉林省龙岗山脉\n中国古代少数民族吐谷浑的省称\n浑天说的简称\n⒈污浊，水不清～浊。～水。\n⒉糊涂～人。他讲的是～话。\n⒊全。满～身是胆。\n⒋天然的璞玉～金。\n浑hùn 1.混杂;混淆。 2.蒙混。 3.胡乱。 4.苟且度过;苟且获取。 5.逗趣的，开玩笑的。\n浑gǔn 1.见\"浑浑\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-浑"},{"id":"glyph-seal-6d53","script":"seal","character":"浓","reading":"nóng","description":"稠密;厚;多\n特指液体或气体中所含某种成分多。与淡”、薄”相对\n⒈含某种成分多，跟\"淡\"相对～茶。～墨。\n⒉深厚，不淡薄～厚。～眉。兴趣很～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-浓"},{"id":"glyph-seal-6d54","script":"seal","character":"浔","reading":"xún","description":"浔阳是江西九江市的别名\n水名\n浔水,在山东省莒县东南,西南流注入沭水\n浔江,在广西东部,即西江中游桂平县至梧州市段的别称\n海洋测量中计算水深的单位\n⒈水边。\n⒉江西省九江市的简称。\n浔yín 1.见\"浸浔\"。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-浔"},{"id":"glyph-seal-6d59","script":"seal","character":"浙","reading":"zhè","description":"zhè：〔～江〕ａ．古水名，今中国钱塘江及其上流的总称。亦称渐江”、之江”、曲江”；ｂ．省名，位于中国东部。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-浙"},{"id":"glyph-seal-6d5a","script":"seal","character":"浚","reading":"xùn；jùn","description":"jùn：(1)疏通，挖深疏～。～河。～泥船。\n(2)深～哲（深沉而有智慧）。\n(3)掘取，榨取。\nxùn：〔～县〕地名，在中国河南省。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-浚"},{"id":"glyph-seal-6d5e","script":"seal","character":"浞","reading":"zhuó","description":"zhuó：淋，使湿让雨～了。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-浞"},{"id":"glyph-seal-6d63","script":"seal","character":"浣","reading":"huàn","description":"huàn：(1)洗～衣。～纱。～雪。～濯。\n(2)中国唐代定制，官吏十天一次休息沐浴，每月分为上、中、下浣，后借作上旬、中旬、下旬的别称。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-浣"},{"id":"glyph-seal-6d65","script":"seal","character":"浥","reading":"yì","description":"湿润，沾湿，如“渭城朝雨浥轻尘”。","enabled":true,"collection":"篆字扩展","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-seal-6d66","script":"seal","character":"浦","reading":"pǔ","description":"pǔ：(1)水边或河流入海的地区。\n(2)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-浦"},{"id":"glyph-seal-6d69","script":"seal","character":"浩","reading":"hào","description":"hào：水大，引申为大和多～大。～繁。～荡。～瀚。～劫。～淼（亦作浩渺”）。～气（盛大刚直之气）。～如烟海。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-浩"},{"id":"glyph-seal-6d6a","script":"seal","character":"浪","reading":"làng","description":"làng：(1)大波波～。～。巨～。风～。～涛。～潮（亦喻大规模的社会运动）。风平～静。\n(2)像波浪起伏的麦～。声～。\n(3)没有约束，放纵放～。流～。～费。～迹。～人。孟～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-浪"},{"id":"glyph-seal-6d6e","script":"seal","character":"浮","reading":"fú","description":"fú：(1)漂在水面上，与沉”相对～桥。～力。～标。～萍。～泛。～沉。漂～。～光掠影。\n(2)表面的～皮儿。～土。～雕。\n(3)空虚，不切实～夸。～华。\n(4)不沉静，不沉着轻～。～躁。\n(5)暂时的～记。～支。\n(6)可移动的～财。～荡。～吊。～动。\n(7)超过，多余人～于事。\n(8)呈现，涌现～现。～想。\n(9)中医指脉搏浮在肌肤表层～脉。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-浮"},{"id":"glyph-seal-6d6f","script":"seal","character":"浯","reading":"wú","description":"wú：〔～水〕水名，在中国山东省。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-浯"},{"id":"glyph-seal-6d74","script":"seal","character":"浴","reading":"yù","description":"yù：洗身，洗澡沐～。～室。～场。～缸。～巾。～血（全身浸于血中，形容战斗激烈）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-浴"},{"id":"glyph-seal-6d77","script":"seal","character":"海","reading":"hǎi","description":"广阔的咸水水域。","enabled":true,"collection":"常用汉字","source":"原有内置文字简注；汉字按常用义说明，彝藏文字按音节或字母名说明。"},{"id":"glyph-seal-6d78","script":"seal","character":"浸","reading":"jìn","description":"jìn：(1)泡，使渗透～泡。～透。～种（zhǒng）。～渍。～没（mò）。沉～（亦称浸沉”）。\n(2)逐渐～染。～渐。～润。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-浸"},{"id":"glyph-seal-6d82","script":"seal","character":"涂","reading":"tú","description":"古水名。即今云南省之牛栏江。发源于寻甸,北流至威宁折向西北,至鲁甸县注入金沙江\n洞涡水支流。在山西省榆次县境\n道路。也作途”\n⒈抹刷，粉饰～抹。～刷。～饰。～油漆。\n⒉抹去～掉。～改。\n⒊乱写，乱画～鸦。不要乱～。\n⒌通\"途\"。道路。\n涂dù 1.以金饰物◇作\"镀\"。\n涂chú 1.通\"除\"。扫除。 2.古月名。称十二月。参见\"涂月\"。 3.古水名。即今安徽省合肥市东北之滁河，至江苏省六合县东南流入长江。\n涂yé 1.见\"涿涂山\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-涂"},{"id":"glyph-seal-6d85","script":"seal","character":"涅","reading":"niè","description":"niè：(1)可做黑色染料的矶石～石。\n(2)以黑色染物，以墨涂物～字（在身上刺字涂墨）。～面。～齿。～而不缁（喻品格高尚，不受外界污染）。\n〔～槃〕佛教指超脱生死的最高境界◇亦作僧人的代称。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-涅"},{"id":"glyph-seal-6d88","script":"seal","character":"消","reading":"xiāo","description":"xiāo：(1)溶化，散失烟～云散。～融（亦作消溶”）。～失。～逝。～亡。～沉。～极。～化。\n(2)灭掉，除去～除。～灭。～毒。～炎。\n(3)把时间度过去～夜。～夏。～闲。～遣。～磨（mó）。\n(4)减少，损失，耗费～耗。～损。～退。\n(5)需要不～说。\n(6)中医学病名～疾。～渴。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-消"},{"id":"glyph-seal-6d89","script":"seal","character":"涉","reading":"shè","description":"shè：(1)步行过水～渡。～江。跋～。\n(2)到，经历～世（经历世事）。～历。～险。～足。\n(3)牵连，关连～及。～嫌。～外（涉及与外国关系的）。交～。牵～。～猎。\n(4)动，着（zhuó）～笔。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-涉"},{"id":"glyph-seal-6d8c","script":"seal","character":"涌","reading":"yǒng；chōng","description":"yǒng：(1)水由下向上冒出来～泉。～流。汹～。泪如泉～。\n(2)像水涌出～现。～动。风起云～。天边～出一轮明月。\nchōng：方言，河汊。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-涌"},{"id":"glyph-seal-6d91","script":"seal","character":"涑","reading":"sù","description":"sù：〔～水〕水名，在中国山西省。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-涑"},{"id":"glyph-seal-6d93","script":"seal","character":"涓","reading":"juān","description":"juān：(1)细小的流水～～。～滴。～埃（喻微末）。\n(2)选择～吉。\n(3)除去，清除～除不洁。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-涓"},{"id":"glyph-seal-6d94","script":"seal","character":"涔","reading":"cén","description":"cén：(1)连续下雨，积水成涝。\n(2)泪落很多的样子～泪。\n〔～～〕ａ．形容汗、泪、水等不断地流下；ｂ．形容天色阴晦；ｃ．形容头脑胀痛。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-涔"},{"id":"glyph-seal-6d95","script":"seal","character":"涕","reading":"tì","description":"tì：(1)眼泪痛哭流～。感激～零。～泣。\n(2)鼻子里分泌的液体鼻～。～泪（鼻涕和眼泪）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-涕"},{"id":"glyph-seal-6d9b","script":"seal","character":"涛","reading":"tāo","description":"像波涛一样的声音\n⒈大波浪波～。\n⒉像波涛的声音松～。\n涛cháo 1.潮汐。\n涛dào 1.覆盖。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-涛"},{"id":"glyph-seal-6d9d","script":"seal","character":"涝","reading":"lào","description":"又名潦水。在陕西省户县、周至两县界上,源出秦岭,为关中八川之一\n汾水支流。源出山西省浮山县西北,西流至临汾市北注入汾水\n水淹没;雨多成灾\n浇水,灌溉\n公今早晚班\n涝láo 1.水名。在今陕西省境内，为关中八川之一。 2.水名。在今山西省境内，源出浮山县黑山，西流合潏水，至临汾市北入汾水。 3.大波。 4.同\"捞\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-涝"},{"id":"glyph-seal-6d9e","script":"seal","character":"涞","reading":"lái","description":"指涞水,又名拒马河,发源于河北省涞源县","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-涞"},{"id":"glyph-seal-6d9f","script":"seal","character":"涟","reading":"lián","description":"小波,风吹水面所形成的波纹\n水名\n在江苏省涟水县北,一名涟河\n在湖南省中部,源出新邵县,东流经湘乡,至湘潭注入湘江\n泪流不断的样子\n细微\n涟lián风吹水面所起的波纹。\n①细小的水波。\n②泪流不止的样子涕泣～漪。\n涟lán 1.大波。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-涟"},{"id":"glyph-seal-6da0","script":"seal","character":"涠","reading":"wéi","description":"混浊的积水","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-涠"},{"id":"glyph-seal-6da3","script":"seal","character":"涣","reading":"huàn","description":"huàn：散开～散。～然冰释（像冰遇到热，一下子消融；喻疑虑、困难或误会完全消除）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-涣"},{"id":"glyph-seal-6da4","script":"seal","character":"涤","reading":"dí","description":"除,清除\n打扫\n涤宫,古代宫中饲养祭祀牲畜的房子\n涤 dí洗～除、洗～。\n【涤荡】同'荡涤'。洗涤；清除。\n【涤纶】一种合成纤维。用乙二醇、对苯二甲酸二甲酯等原料合成。\n【涤罪所】见【炼狱】。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-涤"},{"id":"glyph-seal-6da6","script":"seal","character":"润","reading":"rùn","description":"修饰,使有光彩\n⒈潮湿，不干枯湿～。滋～。雨～万物。\n⒉加油或水，使不干燥～肤膏。～嗓子。\n⒊细腻，光滑丰～。光～。\n⒋修饰，使有光彩～饰。～色。\n⒌利益利～。分～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-润"},{"id":"glyph-seal-6daa","script":"seal","character":"涪","reading":"fú","description":"fú：〔～江〕水名，在中国四川省中部，注入嘉陵江。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-涪"},{"id":"glyph-seal-6dab","script":"seal","character":"涫","reading":"guàn；guān","description":"guān：沸滚～沸。～汤（沸腾的水）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-涫"},{"id":"glyph-seal-6daf","script":"seal","character":"涯","reading":"yá","description":"yá：(1)水边，泛指边际～～。～际。～岸。～垠。生也有～，而知也无～。”\n(2)范围，限度生～。～分（fèn）（限度，本分）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-涯"},{"id":"glyph-seal-6db2","script":"seal","character":"液","reading":"yè","description":"yè：(1)能流动、有一定体积而没有一定形状的物质～体。～汁。～晶。～态。血～。精～。溶～。津～。\n(2)澄清凡为弓，冬析干而春～角”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-液"},{"id":"glyph-seal-6db5","script":"seal","character":"涵","reading":"hán","description":"hán：(1)包容，包含～蓄。～容。～养（ａ．蓄积并保持，如～～水源”；ｂ．指修养，如他很有～～”）。包～。蕴～。～。\n(2)沉，潜～泳（水中潜行，喻深入体会）。～淹。～濡（浸渍，滋润）。\n(3)公路或铁路下面通沟渠的管道～洞。桥～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-涵"},{"id":"glyph-seal-6db8","script":"seal","character":"涸","reading":"hé","description":"hé：水干干～。～泽。～竭。～辙之鲋（喻处境十分危难、急待救助的人）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-涸"},{"id":"glyph-seal-6dbf","script":"seal","character":"涿","reading":"zhuō","description":"zhuō：水滴。\n〔～鹿〕\n〔～州〕地名，均在中国河北省。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-涿"},{"id":"glyph-seal-6dc0","script":"seal","character":"淀","reading":"diàn","description":"蓝靛。一种蓝色染料\n淤积\n沉淀\n①浅的湖泊白洋～。\n②液体中沉下去的东西～粉。\n马铃薯的块茎中，是主要的碳水化合物食品，用于烹调菜肴，工业上用来制酒精、糖等。直链结构的淀粉遇碘呈蓝色。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-淀"},{"id":"glyph-seal-6dc5","script":"seal","character":"淅","reading":"xī","description":"xī：淘米百姓开门而待之～，～米而储之，唯恐其不来也”。\n〔～～〕象声词，形容轻微的风雨声，如秋风～～吹我衣”。\n〔～沥〕象声词，形容雨雪声，落叶声，风声，如霰～～而先集，雪纷糅而遂多”。叠用作淅淅沥沥”，如～～～～下起雨来”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-淅"},{"id":"glyph-seal-6dc6","script":"seal","character":"淆","reading":"xiáo","description":"xiáo：混乱，错杂～乱。混～。～惑。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-淆"},{"id":"glyph-seal-6dc7","script":"seal","character":"淇","reading":"qí","description":"qí：〔～水〕水名，源出中国河南省淇山，流入卫河。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-淇"},{"id":"glyph-seal-6dcb","script":"seal","character":"淋","reading":"lín；lìn","description":"lín：浇～浴。～湿。日晒雨～。\n〔～漓〕ａ．沾湿或流滴，如大汗～～”；ｂ．畅快，如～～尽致。”\nlìn：(1)过滤过～。\n(2)一种性病，病原体是淋病球菌。病人尿道红肿溃烂，尿有浓血。通称淋病”；亦称白浊”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-淋"},{"id":"glyph-seal-6dd1","script":"seal","character":"淑","reading":"shū","description":"shū：(1)善，美（多指女性）～质（善良的品质）。～丽。～静。～慎。～德。～女。\n(2)清澈～清。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-淑"},{"id":"glyph-seal-6dd6","script":"seal","character":"淖","reading":"nào；chuò；zhuō","description":"nào：(1)烂泥，泥沼泥～。污～。～泞（泥泞）。\n(2)柔和。\n〔～尔〕蒙语，湖泊，如罗布～～”（即罗布泊”，在中国新疆维吾尔自治区）。\nchuò：古同绰”，绰约。\nzhuō：姓。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-淖"},{"id":"glyph-seal-6dd9","script":"seal","character":"淙","reading":"cóng","description":"cóng：水声，水流～～。～流（水流）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-淙"},{"id":"glyph-seal-6de0","script":"seal","character":"淠","reading":"pì","description":"水名，淠河，在安徽省。","enabled":true,"collection":"篆字扩展","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-seal-6de1","script":"seal","character":"淡","reading":"dàn","description":"dàn：(1)含盐分少，与咸”相对味～。～水。～化。\n(2)浅，薄，含某种成分少，与浓”相对～酒。～绿。～薄。浅～。～雅。天高云～。\n(3)不热心冷～。～泊（对名利不热心）。～漠。～忘。恬～。\n(4)营业不旺盛～季。\n(5)无关紧要，无聊扯～。～话。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-淡"},{"id":"glyph-seal-6de4","script":"seal","character":"淤","reading":"yū","description":"yū：(1)水道被泥沙阻塞～塞。～积。～滞。～埋。\n(2)河沟中沉积的泥沙～泥。～溉。\n(3)同瘀”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-淤"},{"id":"glyph-seal-6de6","script":"seal","character":"淦","reading":"gàn","description":"gàn：(1)水入船中。\n(2)河工称起伏很大的激浪。\n(3)姓。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-淦"},{"id":"glyph-seal-6deb","script":"seal","character":"淫","reading":"yín","description":"yín：(1)过多，过甚～辞。～雨。～威。\n(2)渐浸，浸渍浸～。\n(3)迷惑富贵不能～。\n(4)在男女关系上态度或行为不正当奸～。～荡。～乱。～秽。～猥。～书。\n(5)放纵，沉溺～湎（沉溺于酒）。骄奢～逸。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-淫"},{"id":"glyph-seal-6dec","script":"seal","character":"淬","reading":"cuì","description":"cuì：(1)把烧红了的铸件往水或油或其他液体里一浸立刻取出来，用以提高合金的硬度和强度～火。～砺。～勉。\n(2)染得赵人徐夫人之匕首，取之百金，使工以药～～之”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-淬"},{"id":"glyph-seal-6dee","script":"seal","character":"淮","reading":"huái","description":"huái：〔～河〕水名，源于中国河南省桐柏山，流经安徽、江苏两省入洪泽湖。简称淮”，如～北”。～南”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-淮"},{"id":"glyph-seal-6df1","script":"seal","character":"深","reading":"shēn","description":"shēn：(1)从表面到底或从外面到里面距离大，与浅”相对～水。～山。～邃。～渊。～壑。～海。～耕。～呼吸。～藏若虚（把珍贵的东西深藏起来，好像没有一样，喻人有知识才能但不在人前表现）。～居简出。\n(2)从表面到底的距离～度。～浅。。水～三尺。\n(3)久，时间长～夜。～秋。年～日久。\n(4)程度高的～思。～知。～交。～造。～谈。～省（xǐng）（深刻的警悟。亦作深醒”）。～究。～奥。～切。～沉（ａ．形容程度深，如暮色～～”；ｂ．声音低沉，如～～的哀鸣”；ｃ．思想感情不外露，如他为人～～，叫人难以捉摸”）。～谋远虑。\n(5)颜色浓～色。～红。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-深"},{"id":"glyph-seal-6df3","script":"seal","character":"淳","reading":"chún；zhūn","description":"chún：(1)朴实～朴。～厚。～古。～风（质朴敦厚的风气）。\n(2)成对。\n(3)古同醇”，酒味厚、纯。\nzhūn：浇灌～而渍之”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-淳"},{"id":"glyph-seal-6df7","script":"seal","character":"混","reading":"hùn；hún","description":"hùn：(1)搀杂在一起～杂。～和。～同。～淆。～为一谈。\n(2)乱，胡乱～乱。～世魔王。\n(3)蒙，充蒙～。～充。～进。鱼目～珠。\n(4)苟且度过胡～。～事。\nhún：同浑”①②。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-混"},{"id":"glyph-seal-6df9","script":"seal","character":"淹","reading":"yān","description":"yān：(1)浸没（mò）水～。～没（mò）。～灌。\n(2)皮肤被汗液浸渍胳肢窝被汗～得又痛又痒。\n(3)广～博。～通。～贯（渊博而贯通）。～雅（渊博高雅）。\n(4)滞，久留～留。久～。～滞。～月（滞留一月）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-淹"},{"id":"glyph-seal-6e05","script":"seal","character":"清","reading":"qīng","description":"清澈、洁净，也可形容清静。","enabled":true,"collection":"常用汉字","source":"原有内置文字简注；汉字按常用义说明，彝藏文字按音节或字母名说明。"},{"id":"glyph-seal-6e0a","script":"seal","character":"渊","reading":"yuān","description":"深潭\n⒈深水，潭深～。鱼跃于～。\n⒉深，深远学识～博。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-渊"},{"id":"glyph-seal-6e0c","script":"seal","character":"渌","reading":"lù","description":"lù：(1)水清～水。～波。\n(2)古同漉”，渗滤。\n〔～水〕水名，在中国湖南省。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-渌"},{"id":"glyph-seal-6e0d","script":"seal","character":"渍","reading":"zì","description":"冲洗\n沾染\n飞毛遍绿野,洒血渍芳丛。\n⒈浸，泡～豆。～麻。淹～。\n⒉染渐～。\n⒊积水～水。排～。\n⒋积在物体上难于除去的油、泥、污垢等油～。墨～。\n渍sè 1.雨或泪洒落。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-渍"},{"id":"glyph-seal-6e0e","script":"seal","character":"渎","reading":"dú","description":"大川\n轻慢;不敬\n渎货无厌。╠\n①水沟；小渠。\n②轻慢；对人不敬\n②职～、亵～。\n【渎职】工作不负责任，以致在执行任务时出现重大事故，犯了严重过失。\n【渎职罪】罪名类别。指国家工作人员利用职权或玩忽职守，侵害国家机关、企业、事业单位的正常管理活动，严重桅国家和人民利益的行为。如受贿、玩忽职守、徇私枉法\n等罪。\n渎dòu 1.洞穴。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-渎"},{"id":"glyph-seal-6e10","script":"seal","character":"渐","reading":"jiàn","description":"流入;入\n淹没,浸泡\n熏染,可染\n⒈浸～渍。～染。\n⒉慢慢流入东～于海。〈引〉疏导禹功之大，～九川。\n⒉事物的开端防微杜～。\n渐qián 1.潜伏。\n渐chán 1.山石高峻貌。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-渐"},{"id":"glyph-seal-6e14","script":"seal","character":"渔","reading":"yú","description":"掠夺\n①捕鱼。\n②捕鱼的人。\n③侵占，掠夺。\n④泛指寻觅。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-渔"},{"id":"glyph-seal-6e17","script":"seal","character":"渗","reading":"shèn","description":"水枯竭\n其他事物渐\n渗sēn 1.见\"淋渗\"。\n渗qīn 1.见\"渗淫\"。\n渗lín 1.见\"渗漓\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-渗"},{"id":"glyph-seal-6e1a","script":"seal","character":"渚","reading":"zhǔ","description":"zhǔ：水中小块陆地洲～。～田。鼋头～（中国江苏省无锡市太湖边的一处著名风景区）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-渚"},{"id":"glyph-seal-6e1d","script":"seal","character":"渝","reading":"yú","description":"yú：(1)改变，违背（多指感情或态度）忠贞不～。生死不～。\n(2)中国四川省重庆市的别称。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-渝"},{"id":"glyph-seal-6e20","script":"seal","character":"渠","reading":"qú；jù","description":"qú：(1)水道，特指人工开的河道或水沟～道（亦指途径，门路）。沟～。\n(2)大～帅。～魁（首领）。\n(3)方言，他～侬（他，他们）。～辈。\n(4)车辋，古代车轮的外圈。\njù：岂掾部～有其人乎？”","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-渠"},{"id":"glyph-seal-6e21","script":"seal","character":"渡","reading":"dù","description":"dù：(1)横过水面～船。～桥。～河。摆～。强～。远～重洋。\n(2)由此到彼～过难关。\n(3)转手，移交引～。\n(4)过河的地方～口。～头。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-渡"},{"id":"glyph-seal-6e25","script":"seal","character":"渥","reading":"wò","description":"wò：(1)沾湿，沾润。\n(2)浓，厚～味（味浓）。～恩。～惠。优～（优越丰厚）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-渥"},{"id":"glyph-seal-6e29","script":"seal","character":"温","reading":"wēn","description":"wēn：(1)不冷不热～带。保～。降～。～泉。～和。～床。\n(2)性情柔和～柔。～存（抚慰体贴）。～情。～顺。～静。～良。～文尔雅。\n(3)稍微加热把酒～一下。\n(4)复习～习。～故而知新。\n(5)古同瘟”。\n(6)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-温"},{"id":"glyph-seal-6e2b","script":"seal","character":"渫","reading":"xiè","description":"xiè：(1)除去，淘去污泥。\n(2)泄，疏通。\n(3)姓。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-渫"},{"id":"glyph-seal-6e2d","script":"seal","character":"渭","reading":"wèi","description":"wèi：〔～河〕水名，源出中国甘肃省，流入陕西省，会泾水入黄河。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-渭"},{"id":"glyph-seal-6e2f","script":"seal","character":"港","reading":"gǎng；jiǎng","description":"gǎng：(1)江河的支流～汊。\n(2)可以停泊大船的江海口岸商～。军～。～口。～湾。～务。\n(3)指香港”～府。～币。～商。\njiǎng：方言，指山凹或山沟（多用于地名）前头～。上～。下～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-港"},{"id":"glyph-seal-6e34","script":"seal","character":"渴","reading":"kě","description":"kě：(1)口干想喝水口～。解～。\n(2)喻迫切地～望。～盼。～慕。～求。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-渴"},{"id":"glyph-seal-6e38","script":"seal","character":"游","reading":"yóu","description":"yóu：(1)人或动物在水里行动～泳。～水。\n(2)不固定～资。～走。～牧。～行。～学（古指离开本乡到外地或外国求学）。～击。～弋。～离。～子（离家久居外乡的人）。\n(3)河流的一段上～。中～。下～。\n(4)交往，来往交～。\n(5)从容地行走周～。～历。～逛。～兴（xìng）。～记。～说（shuì）。～山玩水。\n(6)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-游"},{"id":"glyph-seal-6e3a","script":"seal","character":"渺","reading":"miǎo","description":"miǎo：(1)微小～小。～不足道。\n(2)水势辽远浩～。～邈。～～。～然。\n(3)茫茫然，看不清楚～茫。～无人迹。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-渺"},{"id":"glyph-seal-6e44","script":"seal","character":"湄","reading":"méi","description":"méi：河岸，水与草交接的地方。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-湄"},{"id":"glyph-seal-6e4d","script":"seal","character":"湍","reading":"tuān","description":"tuān：急流，急流的水～急。～流。～濑（石滩上的急流）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-湍"},{"id":"glyph-seal-6e4e","script":"seal","character":"湎","reading":"miǎn","description":"miǎn：沉迷沉～（多指沉迷于酒色）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-湎"},{"id":"glyph-seal-6e54","script":"seal","character":"湔","reading":"jiān","description":"jiān：洗～洗（ａ．洗濯；ｂ．除去耻辱）。～雪（洗刷罪名，昭雪冤屈）。～祓（涤除污秽、恶习）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-湔"},{"id":"glyph-seal-6e56","script":"seal","character":"湖","reading":"hú","description":"hú：(1)陆地上聚积的大水～泊。～泽。～滩。～荡。～光山色。\n(2)指中国湖北省和湖南省两～。～广。\n(3)指中国湖州（旧地名，在今浙江省吴兴县）～笔。～绉。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-湖"},{"id":"glyph-seal-6e58","script":"seal","character":"湘","reading":"xiāng","description":"xiāng：湖南省的别称～绣。～剧。～菜。～语。\n〔～江〕水名，源出中国广西壮族自治区，经过湖南省，注入洞庭湖。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-湘"},{"id":"glyph-seal-6e5b","script":"seal","character":"湛","reading":"zhàn","description":"zhàn：(1)深精～。～恩（深恩）。～蓝。\n(2)清澈清～。澄～。\n(3)姓。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-湛"},{"id":"glyph-seal-6e5c","script":"seal","character":"湜","reading":"shí","description":"湜shí水清的样子～ ～泉水。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-湜"},{"id":"glyph-seal-6e5f","script":"seal","character":"湟","reading":"huáng","description":"huáng：低洼积水的地方～潦生苹”。\n〔～水〕水名，在中国青海省。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-湟"},{"id":"glyph-seal-6e6b","script":"seal","character":"湫","reading":"qiū；jiǎo","description":"qiū：(1)水潭南有龙兮在山～”。大龙～（瀑布，在中国浙江省雁荡山）。\n(2)凉～兮如风”。\njiǎo：低洼～隘（低湿狭小）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-湫"},{"id":"glyph-seal-6e6e","script":"seal","character":"湮","reading":"yān；yīn","description":"yān：(1)埋没～灭。～没（mò）。\n(2)淤塞，堵塞昔者禹之～洪水，决江河。”\nyīn：同洇”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-湮"},{"id":"glyph-seal-6e72","script":"seal","character":"湲","reading":"yuán","description":"见“潺湲”，形容水缓缓流动的样子。","enabled":true,"collection":"篆字扩展","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-seal-6e7f","script":"seal","character":"湿","reading":"shī","description":"湿tà 1.古水名。\n湿xí 1.通\"隰\"。 2.通\"?\"。低下。\n湿xiè 1.古人名用字。\n湿chì 1.见\"湿湿\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-湿"},{"id":"glyph-seal-6e83","script":"seal","character":"溃","reading":"kuì","description":"⒈水冲破堤坝～决。～溢。大水～出。〈引〉冲破包围～围而出。\n⒉散乱，垮台～散。败将～兵。～不成军。经济崩～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-溃"},{"id":"glyph-seal-6e89","script":"seal","character":"溉","reading":"gài","description":"gài：(1)浇灌灌～。\n(2)洗涤。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-溉"},{"id":"glyph-seal-6e98","script":"seal","character":"溘","reading":"kè","description":"kè：忽然；突然～逝。～谢（溘逝）。～至（忽然而至）。\n〔～～〕ａ．水声，如飞下双鸳鸯，塘水声～～”；ｂ．寒冷的样子，如沙堤十里寒～～”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-溘"},{"id":"glyph-seal-6e9c","script":"seal","character":"溜","reading":"liū；liù","description":"liū：(1)滑行，（往下）滑～冰。\n(2)光滑，平滑，无阻碍～圆。～光。\n(3)趁人不见走开～走。～号。\n(4)同熘”。\nliù：(1)迅急的水流大～。急～。\n(2)顺房檐滴下来的水，房顶上流下的水檐～。承～。\n(3)房檐上安的接雨水用的长水槽水～。\n(4)量词，指行（háng）列，排一～三间房。\n(5)某一地点附近的地方这～儿的果木树很多。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-溜"},{"id":"glyph-seal-6e9f","script":"seal","character":"溟","reading":"míng","description":"míng：海东～。北～有鱼，其名为鲲”。\n〔～～〕ａ．形容潮湿、潮润；ｂ．形容昏暗。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-溟"},{"id":"glyph-seal-6ea2","script":"seal","character":"溢","reading":"yì","description":"yì：(1)充满而流出来～流∮水四～。洋～。充～。～于言表。\n(2)过分～美。～恶。～誉。\n(3)超出～出此数。\n(4)古同镒”，古代重量单位。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-溢"},{"id":"glyph-seal-6ea5","script":"seal","character":"溥","reading":"pǔ","description":"pǔ：(1)广大～博。～原。\n(2)普遍～畅。～天之下，莫非王土”。\n(3)姓。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-溥"},{"id":"glyph-seal-6ea7","script":"seal","character":"溧","reading":"lì","description":"lì：〔～水〕\n〔～阳〕均为地名，均在中国江苏省。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-溧"},{"id":"glyph-seal-6eaa","script":"seal","character":"溪","reading":"xī","description":"xī：山里的小河沟，泛指小河沟山～。清～。～水。～涧。～谷。～壑。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-溪"},{"id":"glyph-seal-6eaf","script":"seal","character":"溯","reading":"sù","description":"sù：(1)逆着水流的方向走～流而上。\n(2)追求根源或回想回～。追～。上～。追本～源。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-溯"},{"id":"glyph-seal-6eb1","script":"seal","character":"溱","reading":"qín；zhēn","description":"zhēn：(1)古水名，在今中国河南省。\n(2)古同臻”，至，到。\n〔～～〕ａ．众多，繁盛，如百谷～～，庶卉蕃芜”；ｂ．出汗的样子，如汗出～～”；ｃ．舒展的样子，如物出～～”。\nqín：〔～潼〕地名，在中国江苏省泰县。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-溱"},{"id":"glyph-seal-6eb2","script":"seal","character":"溲","reading":"sōu","description":"sōu：(1)大小便，特指小便。\n(2)浸泡。\n(3)淘～米。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-溲"},{"id":"glyph-seal-6eb6","script":"seal","character":"溶","reading":"róng","description":"róng：在水中或其他液体中化开～化。～解。～液。～剂。～洞。\n〔～～〕ａ．形容宽广；ｂ．形容水流动；ｃ．形容月色荡漾。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-溶"},{"id":"glyph-seal-6eb7","script":"seal","character":"溷","reading":"hùn","description":"hùn：(1)肮脏，混浊世～浊而莫余知兮”。\n(2)厕所中丞匿于～藩以免”。\n(3)猪圈后产子，捐于猪～中”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-溷"},{"id":"glyph-seal-6eba","script":"seal","character":"溺","reading":"nì；niào","description":"nì：(1)淹没～水。～死。\n(2)沉迷不悟，过分，无节制～爱。沉～。\nniào：同尿1”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-溺"},{"id":"glyph-seal-6ebd","script":"seal","character":"溽","reading":"rù","description":"rù：(1)湿润；闷热～暑。～热。\n(2)味深厚其饮食不～”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-溽"},{"id":"glyph-seal-6ec1","script":"seal","character":"滁","reading":"chú","description":"chú：〔～河〕水名，源出中国安徽省，流至江苏省入长江。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-滁"},{"id":"glyph-seal-6ec2","script":"seal","character":"滂","reading":"pāng","description":"pāng：形容水涌出～流。～沱。～沛。～濞（pì）（ａ．形容水流相击的声音；ｂ．形容雨水量多；ｃ．形容众多）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-滂"},{"id":"glyph-seal-6ec3","script":"seal","character":"滃","reading":"wěng；wēng","description":"wěng：形容云气涌起或水势盛大。wēng：用于水名滃江，在广东省。","enabled":true,"collection":"篆字扩展","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-seal-6ec7","script":"seal","character":"滇","reading":"diān","description":"diān：(1)古族名，在今中国云南省东部滇池附近地区。\n(2)中国云南省的别称～红（云南出产的红茶）。～剧。～池。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-滇"},{"id":"glyph-seal-6ecb","script":"seal","character":"滋","reading":"zī","description":"zī：(1)生出，长～生。～芽。～事。～扰（骚扰生事）。潜～暗长。\n(2)增益，加多～养。～补。～阴。\n(3)汁液，润泽～润。\n(4)味道～味。\n(5)喷射往外～水。\n(6)浊何故使吾水～？”","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-滋"},{"id":"glyph-seal-6ed1","script":"seal","character":"滑","reading":"huá","description":"huá：(1)光溜，不粗涩～溜。光～。～润。～利。\n(2)在光溜的物体表面上溜动～冰。～雪。～行。～翔。～梯。～坡。\n(3)狡诈，不诚实～头。狡～。～头～脑。\n(4)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-滑"},{"id":"glyph-seal-6ed3","script":"seal","character":"滓","reading":"zǐ","description":"zǐ：(1)渣子，沉淀物渣～。油～。\n(2)污黑，污浊垢～。～秽。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-滓"},{"id":"glyph-seal-6ed4","script":"seal","character":"滔","reading":"tāo","description":"tāo：(1)弥漫，充满～天。～～。\n(2)倨慢士不滥，官不～”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-滔"},{"id":"glyph-seal-6ed5","script":"seal","character":"滕","reading":"téng","description":"téng：(1)水向上腾涌；引申张口放言咸其辅颊舌，～口说也”。\n(2)中国周代诸侯国名，在今山东省滕县一带。\n(3)姓。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-滕"},{"id":"glyph-seal-6ede","script":"seal","character":"滞","reading":"zhì","description":"积压。长期积存,未作处理\n停止;阻塞;静止\n滞chì 1.见\"滞沛\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-滞"},{"id":"glyph-seal-6ee1","script":"seal","character":"满","reading":"mǎn","description":"⒈全～分。～身是泥。\n⒉足，够，符合心意～足。心～意足。非常～意。\n⒊充实，没有余地充～。布～。粮食～仓。\n⒋达到一定限度客～。假期将～。\n⒌骄傲，不虚心自～。谦受益，～遭损。\n⒍斟酒，使满～上这杯。\n满mèn 1.通\"懑\"。烦闷。 2.中医学名词。胀满;壅滞。 3.用同\"们\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-满"},{"id":"glyph-seal-6ee5","script":"seal","character":"滥","reading":"làn","description":"大水漫出,泛滥\n浸渍,泡在水里\n⒈大水漫溢泛～成灾。〈引〉过度，无节制～用职权。\n⒉失真，不切实际采～忽真。～竽充数。陈词～调。\n滥jiàn 1.泉水涌出貌。参见\"滥泉\"。 2.古水名。\n滥lǎn 1.以干果浸渍于水中作成的饮料。 2.谓以盐等腌渍食物。 3.揽聚。\n滥lán 1.春秋邾邑名，在今山东省滕县﹑枣庄市之间。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-滥"},{"id":"glyph-seal-6ee9","script":"seal","character":"滩","reading":"tān","description":"滩头。指江、河、湖、海边水涨淹没、水退显露的淤积平地\n等级\n这种奴隶叫作三滩娃子”。滩是等级的意思。管家娃子为头滩,普通娃子为\n⒈江、河或海边泥沙淤积的平地。也指水中的沙洲河～。～。沙～。\n⒉水浅、多石、流急的地方险～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-滩"},{"id":"glyph-seal-6eeb","script":"seal","character":"滫","reading":"xiǔ","description":"滫xiǔ淘米水。〈引〉脏水。臭水。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-滫"},{"id":"glyph-seal-6ef4","script":"seal","character":"滴","reading":"dī","description":"dī：(1)液体一点一点地向下落～眼药。～落。～翠。水～石穿（喻只要有恒心，不断努力，事情一定能成功，亦作滴水穿石”）。～漏（漏壶）。\n(2)一点一点向下落的液体水～」～。\n(3)量词，用于滴下的液体的数量～水不漏。两～墨水。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-滴"},{"id":"glyph-seal-6f02","script":"seal","character":"漂","reading":"piāo；piǎo；piào","description":"piāo：浮在液体上不动或顺着风向、流向而移动～浮。～流。～没（mò）。～移。～泊（喻职业生活不固定，东奔西走。亦作飘泊”）。～零。～沦。～游。～萍。\npiǎo：(1)用水加药品使物品退去颜色或变白～白。～染。\n(2)用水冲去杂质～洗。\npiào：方言，事情、账目等落空那事没什么指望，～了。\n〔～亮〕ａ．好看，如长得～～”；ｂ．出色，如这件事办得～～”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-漂"},{"id":"glyph-seal-6f06","script":"seal","character":"漆","reading":"qī","description":"qī：(1)落叶乔木，树皮内富含树脂，与空气接触后呈褐色，即生漆”，可制涂料，液汁干后可入药。\n(2)用漆树皮的黏汁或其他树脂做成的涂料油～。～片。～器；～雕；磨～画（均为工艺品）。～包线。\n(3)用漆涂把门窗～一下。\n(4)黑～黑一团（ａ．形容非弛暗，没有一点光明；ｂ．形容一无所知。均亦作一团漆黑”）。\n(5)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-漆"},{"id":"glyph-seal-6f09","script":"seal","character":"漉","reading":"lù","description":"lù：液体慢慢地渗下，滤过渗～。～网（造纸时滤掉纸浆中水分的网）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-漉"},{"id":"glyph-seal-6f0f","script":"seal","character":"漏","reading":"lòu","description":"lòu：(1)物体由孔或缝透过壶里的水～光了。～风。渗～。～泄（ａ．水、光等流出或透出；ｂ．泄露）。～电（跑电）。\n(2)泄露走～消息。～底（泄露内情）。透～。\n(3)脱逃或无意放过疏～。遗～。挂一～万。～网之鱼。\n(4)中医指某些流出脓血黏液的病崩～（子宫大量出血的病）。痔～。\n〔～壶〕古代计时器，铜制有孔，可以滴水或漏沙，有刻度标志以计时间。简称漏”，如铜壶滴～”（亦称铜壶刻漏”），～尽更深”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-漏"},{"id":"glyph-seal-6f14","script":"seal","character":"演","reading":"yǎn","description":"yǎn：(1)根据事理推广发挥推～。讲～（亦作演讲”）。～义（以史书及传说的材料为基础，增添一些细节，用章回体写成的小说）。～绎（一种推理方法，由一般原理推出关于特殊情况下的结论）。\n(2)依照程式练习～练。～示。～算。～武。～习。～兵场。\n(3)不断变化～变。～化。\n(4)把技艺当众表现出来表～。～出。～播。～奏。主～。义～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-演"},{"id":"glyph-seal-6f15","script":"seal","character":"漕","reading":"cáo","description":"cáo：利用水道转运粮食～运（旧时指国家从水道运输粮食，供应京城或接济军需）。～粮。～河。～渠。～船。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-漕"},{"id":"glyph-seal-6f20","script":"seal","character":"漠","reading":"mò","description":"mò：(1)面积阔大无人定居，缺水干燥的沙石地带沙～。～北。\n(2)空旷广～。荒～。～～。\n(3)冷淡地，不经心地～视。～不关心。\n(4)古同寞”，寂静无声。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-漠"},{"id":"glyph-seal-6f29","script":"seal","character":"漩","reading":"xuán","description":"xuán：回旋的水流～涡（ａ．回旋水流形成的螺旋形；ｂ．喻越陷越深不能自拔的境地，如卷入～～”。均亦作旋涡”）。～澴（波浪回旋涌起的样子）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-漩"},{"id":"glyph-seal-6f31","script":"seal","character":"漱","reading":"shù","description":"shù：含水荡洗口腔～口。洗～。盥～（洗手或漱口）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-漱"},{"id":"glyph-seal-6f33","script":"seal","character":"漳","reading":"zhāng","description":"zhāng：〔～河〕水名，源出中国山西省，流至河北省入卫河。\n〔～江〕水名，在中国福建省。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-漳"},{"id":"glyph-seal-6f3e","script":"seal","character":"漾","reading":"yàng","description":"yàng：(1)水面动荡荡～。\n(2)液体溢出来～奶。\n(3)方言，小的湖泊。\n〔～濞（bì）〕ａ．水名，在中国云南省，澜沧江支流；ｂ．地名，在中国云南省。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-漾"},{"id":"glyph-seal-6f47","script":"seal","character":"潇","reading":"xiāo","description":"急疾\n水名。潇水\n⒈水清且深。\n⒉风雨声风雨～ ～。\n⒋潇水，在湖南省。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-潇"},{"id":"glyph-seal-6f4d","script":"seal","character":"潍","reading":"wéi","description":"水名。今称潍河\n古州名。又县名\n潍wéi潍河，在山东省。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-潍"},{"id":"glyph-seal-6f58","script":"seal","character":"潘","reading":"pān","description":"pān：(1)淘米汁。\n(2)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-潘"},{"id":"glyph-seal-6f5c","script":"seal","character":"潜","reading":"qián","description":"qián：(1)隐在水面下活动～水。～泳。～坝。～行（ａ．在水面以下行动；ｂ．在外边秘密行动）。\n(2)隐藏的，秘密地～藏。～伏。～遁。～逃。～力。～心。～师。～在。～台词。～移默化。\n(3)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-潜"},{"id":"glyph-seal-6f5e","script":"seal","character":"潞","reading":"lù","description":"lù：〔～河〕水名，即中国北京市通县以下的北运河。\n〔～江〕水名，即中国云南省的怒江。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-潞"},{"id":"glyph-seal-6f62","script":"seal","character":"潢","reading":"huáng；guāng","description":"huáng：(1)积水池～污。～潦。弄兵～池（造反的讳称。潢池”，即天璜”，本星名，转义为天子之池，借指皇室）。\n(2)染纸装～（ａ．裱褙字画；ｂ．装饰货物的包装；ｃ．物品外表的装饰。均亦作装璜”）。\nguāng：〔～～〕ａ．水深广的样子，如扬流波之～～兮”；ｂ．威武的样子，如武夫～～”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-潢"},{"id":"glyph-seal-6f66","script":"seal","character":"潦","reading":"liáo；lǎo；lào","description":"lǎo：(1)雨水大。\n(2)路上的流水，积水～水。\nlào：古同涝”，雨水过多，水淹。\nliáo：〔～河〕水名，在中国河南省西南部。亦称垢河”。\n〔～倒〕ａ．落拓不羁，举止不自检束；ｂ．颓丧，失意。\n〔～草〕ａ．（做事）草率，不精细；ｂ．（字）不工整。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-潦"},{"id":"glyph-seal-6f6d","script":"seal","character":"潭","reading":"tán","description":"tán：(1)水深之处深～。泥～。水～。\n(2)深～渊。～～（宽深，宽大）。～思（深思。亦作覃思”）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-潭"},{"id":"glyph-seal-6f74","script":"seal","character":"潴","reading":"zhū","description":"zhū：(1)水积聚停～。～积。～留（医学上指液体聚集停留，如尿～～”）。\n(2)水积聚的地方。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-潴"},{"id":"glyph-seal-6f78","script":"seal","character":"潸","reading":"shān","description":"shān：形容流泪～然。～～（流泪不止）。～泫（流泪的样子）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-潸"},{"id":"glyph-seal-6f7a","script":"seal","character":"潺","reading":"chán","description":"chán：〔～～〕ａ．水缓流的样子；ｂ．象声词，溪水、泉水流动的声音。\n〔～湲〕ａ．河水慢慢流的样子；ｂ．涕泪横流的样子。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-潺"},{"id":"glyph-seal-6f7c","script":"seal","character":"潼","reading":"tóng","description":"tóng：〔～关〕ａ．关名，在中国陕西省东部；ｂ．地名，在中国陕西省东部。\n〔～～〕高的样子。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-潼"},{"id":"glyph-seal-6f84","script":"seal","character":"澄","reading":"chéng；dèng","description":"chéng：水静而清～莹。～酒（淡酒）。～汰。～澈。～湛。～廓。～清。～碧。～净。～静。～明。\ndèng：让液体里的杂质沉下去～清。～沙。～泥浆。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-澄"},{"id":"glyph-seal-6f8c","script":"seal","character":"澌","reading":"sī","description":"sī：(1)尽～灭。\n(2)流水候吏还白，河水流～”。\n(3)古同嘶”，声音沙哑。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-澌"},{"id":"glyph-seal-6f8d","script":"seal","character":"澍","reading":"shù；zhù","description":"shù：及时的雨～雨。长吏各洁斋祷请，冀蒙嘉～”。\nzhù：古同注”，灌注。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-澍"},{"id":"glyph-seal-6f9c","script":"seal","character":"澜","reading":"lán","description":"波纹\n澜lán大波浪狂～。推波助～。\n澜làn 1.见\"澜漫\"。 2.见\"澜贱\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-澜"},{"id":"glyph-seal-6fa1","script":"seal","character":"澡","reading":"zǎo","description":"zǎo：沐浴全身，引申为保持节操洗～。～盆。～堂。～雪（洗涤使清洁）。～身浴德（砥砺志行，使身心纯洁清白）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-澡"},{"id":"glyph-seal-6fa5","script":"seal","character":"澥","reading":"xiè","description":"⒈〈古〉海的别称渤～。又指渤海。\n⒉由稠变稀或使其变稀糨糊太～了。粥稠了，加些开水～一～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-澥"},{"id":"glyph-seal-6fa7","script":"seal","character":"澧","reading":"lǐ","description":"lǐ：〔～水〕水名，在中国湖南省。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-澧"},{"id":"glyph-seal-6fb3","script":"seal","character":"澳","reading":"ào","description":"ào：(1)海边弯曲可以停船的地方（多用于地名）～门（简称澳”）。\n(2)指澳大利亚洲”（大洋洲”的旧称，简称澳洲”）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-澳"},{"id":"glyph-seal-6fb6","script":"seal","character":"澶","reading":"chán","description":"chán：水流平静～湉。\n〔～渊〕ａ．古湖名，故址在今中国河南省濮阳市西；ｂ．古地名，在今中国安徽省萧山市一带。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-澶"},{"id":"glyph-seal-6fb9","script":"seal","character":"澹","reading":"dàn；tán","description":"dàn：(1)恬静、安然的样子～泊。～漠。～薄。恬～。\n(2)水波纡缓的样子～淡。～～。\ntán：〔～台〕复姓。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-澹"},{"id":"glyph-seal-6fc0","script":"seal","character":"激","reading":"jī","description":"jī：(1)水受阻遏，震荡而涌或飞溅冲～。～荡。～浊扬清（冲击污水，让清水上来，喻打击坏人坏事，奖励好人好事）。\n(2)冷水突然浇淋或冲、泡食物～酸菜。\n(3)鼓动，使人的感情冲动刺～。～励。\n(4)感情冲动感～。～动。～昂慷慨。\n(5)急剧的，强烈的～烈。～进。\n(6)过分直率～厉。～切。\n(7)鲜明唇如～丹。\n〔～光〕某些物质的原子中的粒子受光或电刺激，使低能级的原子变成高能级原子，而辐射出相位、频率、方向等完全相同的光，称激光”。亦称莱塞”、镭射”。\n〔～光器〕产生激光的装置。\n〔～素〕内分泌腺分泌的物质。亦称荷尔蒙”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-激"},{"id":"glyph-seal-6fd1","script":"seal","character":"濑","reading":"lài","description":"从沙石上流过的水\n流得很急的水;急流\n濑lài急流的水。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-濑"},{"id":"glyph-seal-6fd2","script":"seal","character":"濒","reading":"bīn","description":"靠近;临近\n濒 bīn接近南～长江、～临绝境。\n【濒临】紧接～太平洋、～崩溃。\n【濒危】接近危难。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-濒"},{"id":"glyph-seal-6fde","script":"seal","character":"濞","reading":"bì；pì","description":"bì：〔漾～〕见漾”。\npì：〔滂～〕见滂”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-濞"},{"id":"glyph-seal-6fe1","script":"seal","character":"濡","reading":"rú","description":"rú：(1)沾湿，润泽～笔。～湿。～染。耳～目染。相～以沫（沫”，唾沫，喻同处困境，以微薄之力相互救助）。\n(2)停留，迟滞～滞。\n(3)含忍～忍。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-濡"},{"id":"glyph-seal-6fee","script":"seal","character":"濮","reading":"pú","description":"pú：姓。\n〔～阳〕地名，在中国河南省。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-濮"},{"id":"glyph-seal-6fef","script":"seal","character":"濯","reading":"zhuó；zhào","description":"zhuó：(1)洗～足。\n(2)祓除罪恶。\n〔～～〕形容山无草木，光秃秃的，如～～童山”。\nzhào：古通棹”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-濯"},{"id":"glyph-seal-7011","script":"seal","character":"瀑","reading":"bào；pù","description":"pù：〔～布〕水从高山陡直地流下来，远看好像挂着的白布。简称瀑”，如飞～流泉”。\nbào：暴雨。\n〔～河〕水名，在中国河北省。亦作鲍河”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-瀑"},{"id":"glyph-seal-701b","script":"seal","character":"瀛","reading":"yíng","description":"yíng：(1)海～海。～洲（古代神话中仙人居住的山，在海上）。～眷（仙眷，常用作对别人眷属的敬称）。～寰（地球水陆的总称，指全世界）。\n(2)姓。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-瀛"},{"id":"glyph-seal-7023","script":"seal","character":"瀣","reading":"xiè","description":"xiè：〔沆～〕见沆”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-瀣"},{"id":"glyph-seal-704c","script":"seal","character":"灌","reading":"guàn","description":"guàn：(1)浇地～溉。～渠。浇～。\n(2)注入液体～注。～浆。～肠。\n(3)指录音～唱片。\n(4)炼铸。\n(5)丛生，亦指丛生的树木～木。～丛。\n(6)古代祭祀的一种仪式，斟酒浇地降神。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-灌"},{"id":"glyph-seal-704f","script":"seal","character":"灏","reading":"hào","description":"豆浆\n水势无边际。通浩”\n广大\n灏 hào广大，无边无际。水势大。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-灏"},{"id":"glyph-seal-706b","script":"seal","character":"火","reading":"huǒ","description":"huǒ：(1)燃烧，物质燃烧时所发出的光和焰～力。～烛。～源。～焰。烟～。～中取栗（喻为别人冒险出力，而自己吃亏上当，毫无所获）。\n(2)紧急～速。十万～急。\n(3)指枪炮弹药等～药。～炮。\n(4)发怒，怒气～暴。～性。\n(5)中医指发炎、红肿、烦躁等的病因肝～。毒～攻心。\n(6)形容红色的～红。～腿。\n(7)古代军队组织，一火十个人。\n(8)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-火"},{"id":"glyph-seal-706d","script":"seal","character":"灭","reading":"miè","description":"⒈熄，熄火～ 火。～灯。熄～。\n⒉使不存在～亡。消～。磨～。毁～。\n⒊淹没～顶。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-灭"},{"id":"glyph-seal-7070","script":"seal","character":"灰","reading":"huī","description":"huī：(1)物体燃烧后剩下的东西，经烧制后形成的产品纸～。～烬。洋～。～飞烟灭。\n(2)尘土～尘。\n(3)特指石灰”～墙。～膏。\n(4)黑白之间的颜色～色。～质（脑和脊髓的灰色部分）。～沉沉。\n(5)志气消沉心～意懒。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-灰"},{"id":"glyph-seal-7075","script":"seal","character":"灵","reading":"líng","description":"古时楚人称跳舞降神的巫为灵\n神灵\n⒈有效验～验。～丹妙药。\n⒉聪明，机敏，敏捷～敏。～活。～机。心～手巧。\n⒊活动迅速，准确这部仪器很～。失～。\n⒋传说中或迷信者称\"神\"及\"关于神仙\"的神～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-灵"},{"id":"glyph-seal-7078","script":"seal","character":"灸","reading":"jiǔ","description":"jiǔ：烧，中医的一种医疗方法。用艾叶等制成艾炷或艾卷，烧灼或熏烤人身的穴位针～（针刺与艾灸的合称）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-灸"},{"id":"glyph-seal-707c","script":"seal","character":"灼","reading":"zhuó","description":"zhuó：(1)烧，炙～热。～伤（烧伤）。焦～。心急如～。\n(2)明白透彻真知～见。\n(3)鲜明～～。～亮。～然。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-灼"},{"id":"glyph-seal-707e","script":"seal","character":"灾","reading":"zāi","description":"zāi：(1)水、火、荒旱等所造成的祸害水～。火～。～难（nàn）。～害。～患。\n(2)个人的不幸遭遇招～惹祸。幸～乐祸。破财消～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-灾"},{"id":"glyph-seal-707f","script":"seal","character":"灿","reading":"càn","description":"鲜艳;鲜明\n明白,清楚\n灿 cǎn灿烂】鲜明耀眼星光～。\n灿càn 1.明亮貌。 2.鲜艳貌;鲜明貌。 3.明白，清楚。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-灿"},{"id":"glyph-seal-7080","script":"seal","character":"炀","reading":"yáng","description":"熔炼金属\n遮蔽,蒙蔽,挡住\n炽热\n观天火之炎炀兮,听\n⒈也作\"烊\"。熔化金属。\n⒉火旺。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-炀"},{"id":"glyph-seal-7085","script":"seal","character":"炅","reading":"guì；jiǒng","description":"jiǒng：火光。\nguì：姓。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-炅"},{"id":"glyph-seal-7089","script":"seal","character":"炉","reading":"lú","description":"火炉\n炉上有壶。\n为炉,为壶。\n古代酒店前放置酒坛的土台\n⒈取暖、做饭、冶炼等用的供热器具手～。电磁～。煤气～子。炼钢～子。\n⒉\"鑪\"另见rfum。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-炉"},{"id":"glyph-seal-708a","script":"seal","character":"炊","reading":"chuī","description":"chuī：烧火做饭～事。～烟。巧妇难为无米之～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-炊"},{"id":"glyph-seal-708e","script":"seal","character":"炎","reading":"yán","description":"yán：(1)热～热。～凉（ａ．气候的热和冷；ｂ．喻人情势利，或亲热攀附，或冷漠疏远，反复无常）。趋～附势。～～（灼热；火炽盛；引申为兴盛，亦指威势显赫）。\n(2)身体的一部分发生红、肿、热、痛的现象～症。\n(3)传说中的中国上古帝王中的一位，并成为中华民族千百年的象征～帝。～黄。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-炎"},{"id":"glyph-seal-7095","script":"seal","character":"炕","reading":"kàng","description":"kàng：(1)北方用砖、坯等砌成的睡觉的台，下面有洞，连通烟囱，可以烧火取暖～席。火～。土～。\n(2)烤把湿衣服放在火边～一～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-炕"},{"id":"glyph-seal-7099","script":"seal","character":"炙","reading":"zhì","description":"zhì：(1)烤～兔。焚～忠良。～手可热（热得烫手，喻权贵气焰很盛）。\n(2)烤肉脍～人口（美味人人爱吃，喻好的诗文、事物大家都称赞）。\n(3)喻受到熏陶亲～（直接得到某人的教诲或传授）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-炙"},{"id":"glyph-seal-709c","script":"seal","character":"炜","reading":"wěi","description":"同辉”。光;光辉\n炜huī 1.光;光辉。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-炜"},{"id":"glyph-seal-70ab","script":"seal","character":"炫","reading":"xuàn","description":"xuàn：(1)光明照耀光彩～目。\n(2)夸耀～耀。～鬻（夸耀卖弄）。～弄。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-炫"},{"id":"glyph-seal-70ad","script":"seal","character":"炭","reading":"tàn","description":"tàn：(1)把木材和空气隔绝，加高热烧成的一种黑色燃料木～。～素。～笔。～画。\n(2)像炭的东西山楂～。\n(3)煤石～。焦～。泥～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-炭"},{"id":"glyph-seal-70ae","script":"seal","character":"炮","reading":"pào；páo；bāo","description":"páo：烧～炙。～烙（luò）。～制。\nbāo：(1)把物品放在器物上烘烤或焙把湿衣服搁在热炕上～干。\n(2)一种烹调方法，在旺火上急炒～羊肉。\npào：(1)重型武器的一类，有迫击炮、高射炮、火箭炮等～兵。～弹。\n(2)爆竹鞭～。花～。\n(3)爆破土石等在凿的眼内装进炸药后称炮”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-炮"},{"id":"glyph-seal-70af","script":"seal","character":"炯","reading":"jiǒng","description":"jiǒng：光明，明亮～心（心地光明）。～介。～戒。～然。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-炯"},{"id":"glyph-seal-70b1","script":"seal","character":"炱","reading":"tái","description":"tái：烟气凝积而成的黑灰（俗称烟子”或煤子”）煤～。松～（松烟）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-炱"},{"id":"glyph-seal-70b3","script":"seal","character":"炳","reading":"bǐng","description":"bǐng：(1)光明，显著彪～。～蔚。～映。～焕。～耀。\n(2)点，燃～烛。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-炳"},{"id":"glyph-seal-70b9","script":"seal","character":"点","reading":"diǎn","description":"细小的黑色斑痕\n小滴\n汉字笔画名\n数学名词。数学上表示小数的符号叫小数点,省称为点”。\n几何系统,尤指欧几里","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-点"},{"id":"glyph-seal-70bc","script":"seal","character":"炼","reading":"liàn","description":"修炼;锻炼;造就\n⒈用加热法制做～焦。～钢材。～乳制品。\n⒉用心琢磨～写字。～造句。～作文。\n炼làn 1.腐烂。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-炼"},{"id":"glyph-seal-70bd","script":"seal","character":"炽","reading":"chì","description":"兴盛,昌盛\n烹煮\n炽 chì热烈旺盛～热。\n【炽烈】旺盛猛烈。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-炽"},{"id":"glyph-seal-70c1","script":"seal","character":"烁","reading":"shuò","description":"热;烫;烤灼\n摇曳;闪烁\n通铄”。销熔\n烁luò 1.见\"爆烁\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-烁"},{"id":"glyph-seal-70c8","script":"seal","character":"烈","reading":"liè","description":"liè：(1)火势猛；引申为猛，厉害～火。～焰。～酒。～马。～性。激～。剧～。\n(2)气势盛大轰轰～～。\n(3)刚直，有高贵品格的；为正义而死难的～女。壮～。先～。～士。\n(4)功业功～。\n(5)古同列”，行列。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-烈"},{"id":"glyph-seal-70ca","script":"seal","character":"烊","reading":"yáng；yàng","description":"yáng：(1)熔化金属～铜。～金（金属溶液）。\n(2)溶化糖～了。\nyàng：〔打～〕方言，商店晚上关门停止营业。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-烊"},{"id":"glyph-seal-70d8","script":"seal","character":"烘","reading":"hōng","description":"hōng：(1)用火或蒸气使身体暖和或使物体变热、干燥～箱。～手。～干（gān）。～烤。～焙。\n(2)烧。\n(3)衬托，渲染～衬。～托。～染。～云托月（喻从侧面加以点染以烘托所描绘的事物）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-烘"},{"id":"glyph-seal-70d9","script":"seal","character":"烙","reading":"lào；luò","description":"lào：(1)用器物烫熨～衣服。～印。～花（亦称烫花”）。\n(2)把面食放在烧热的铛或锅上加热使熟～饼。～锅贴。\nluò：〔炮（páo）～〕见炮1”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-烙"},{"id":"glyph-seal-70db","script":"seal","character":"烛","reading":"zhú","description":"⒈以线绳或苇子做中心，周围用蜡和油脂包裹，点燃取光的东西蜡～成灰泪始干。\n⒉照见，照耀火光～天。〈引〉明察洞～其奸。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-烛"},{"id":"glyph-seal-70dc","script":"seal","character":"烜","reading":"huǐ；xuǎn","description":"xuǎn：(1)盛大，显著～赫。\n(2)晒干风以散之，雨以润之，日以～之”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-烜"},{"id":"glyph-seal-70df","script":"seal","character":"烟","reading":"yān","description":"yān：(1)物质燃烧时所生的气体冒～。硝～。～囱。～雾。～波。～火。～尘。荒无人～。\n(2)像烟的～霞。～霭。～岚。～鬟。\n(3)烟气刺激使眼睛流泪或睁不开～了眼睛。\n(4)一年生草本植物～草。～叶。\n(5)烟草制成品香～。卷～。纸～。～蒂。\n(6)指鸦片”大～。～灯。～枪。～馆。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-烟"},{"id":"glyph-seal-70e6","script":"seal","character":"烦","reading":"fán","description":"烦躁,烦闷\n通繁”。烦琐;繁多\n⒈急躁，苦闷～躁。～闷。心～。莫～恼。\n⒉多、乱、杂～琐。要言不～。～言饰辞，而无实用。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-烦"},{"id":"glyph-seal-70e7","script":"seal","character":"烧","reading":"shāo","description":"⒈使物体着火～ 火。燃～。\n⒉用热能使物体受热起变化～瓦。～饭。～汤。\n⒊烹饪方法之一炒煎～炸。蘑芋～鸭子。\n⒋发热，体温升高发～。高～。～退了。\n⒌用肥过多，致使植物枯萎、死亡～了秧蔸。\n烧shào 1.放火烧野草以肥田。 2.泛指野火。 3.指彩霞。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-烧"},{"id":"glyph-seal-70e8","script":"seal","character":"烨","reading":"yè","description":"火盛,明亮,引伸为光辉灿烂","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-烨"},{"id":"glyph-seal-70ed","script":"seal","character":"热","reading":"rè","description":"满腔热情;热心肠\n有权势的,权势显赫的\n⒈物理学上指凡能使物体温度升高的那种\"能\"叫\"热\"。\n⒉温度高，跟\"冷\"相对～天。～菜。\n⒊使温度升高将饭～一～。\n⒋盛，旺～闹。～货。～门。\n⒌情绪高，情意深～烈。～心。～忱。～爱。\n⒍羡慕眼～。\n①急切地想得到，多含贬义～中名利。\n②酷爱～中下围棋。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-热"},{"id":"glyph-seal-70fd","script":"seal","character":"烽","reading":"fēng","description":"fēng：古代边防报警的烟火～火（ａ．古代边防报警的烟火；ｂ．喻战争或战乱）。～烟。～燧。～火台。～鼓（烽火和战鼓，指战争）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-烽"},{"id":"glyph-seal-7109","script":"seal","character":"焉","reading":"yān","description":"yān：(1)与介词于”加代词是”相当心不在～。不复出～。\n(2)乃，才必知乱之所自起，～能治之。\n(3)文言疑问词，怎么，哪儿且～置土石？\n(4)文言助词又何戚～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-焉"},{"id":"glyph-seal-710a","script":"seal","character":"焊","reading":"hàn","description":"hàn：用熔化金属或塑料来粘合、修补金属或塑料器物～接。～工。～料。～条。～枪。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-焊"},{"id":"glyph-seal-7115","script":"seal","character":"焕","reading":"huàn","description":"huàn：光明～发。～炳（明亮）。～丽。～赫。～蔚。～然一新。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-焕"},{"id":"glyph-seal-7118","script":"seal","character":"焘","reading":"tāo；dao","description":"覆盖。通帱”\n引申为庇荫\n载,承受\n⒈多见于人名。\n焘dào 1.覆盖。 2.荫庇。 3.犹载，承受。 4.见\"焘妔\"。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-焘"},{"id":"glyph-seal-711a","script":"seal","character":"焚","reading":"fén","description":"fén：烧～烧。～毁。～化。～香。～书坑儒。～膏继晷（膏”，油脂；晷”，日影；形容夜以继日地用功读书或努力工作）。忧心如～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-焚"},{"id":"glyph-seal-711c","script":"seal","character":"焜","reading":"kūn","description":"kūn：光明。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-焜"},{"id":"glyph-seal-7126","script":"seal","character":"焦","reading":"jiāo","description":"jiāo：(1)物体经火烧变成黑黄色并发硬、发脆烧～。～土。～头烂额。\n(2)烦躁，着急～急。～虑。～灼。～躁不安。\n(3)酥，脆～脆。～枣。\n(4)喻干燥到极点唇～口燥。～枯。～裂。～渴。\n(5)一种质硬、多孔、发热量高的固体燃料～炭。～煤。～炼。\n(6)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-焦"},{"id":"glyph-seal-712f","script":"seal","character":"焯","reading":"chāo；zhuō","description":"zhuō：明白透彻～见（同灼见”）。～烁。\nchāo：把蔬菜放到沸水中略微一煮就捞出来～菠菜。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-焯"},{"id":"glyph-seal-7130","script":"seal","character":"焰","reading":"yàn","description":"yàn：(1)火光光～。\n(2)火苗火～。烈～。气～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-焰"},{"id":"glyph-seal-7131","script":"seal","character":"焱","reading":"yàn","description":"yàn：火花，火焰。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-焱"},{"id":"glyph-seal-7136","script":"seal","character":"然","reading":"rán","description":"rán：(1)对，是～否。不～。不以为～。\n(2)以为对，答应，信守～纳（以为对而采纳）。～诺（许诺，信守诺言）。\n(3)这样，如此当～。～后。～则。\n(4)表示一种语气（a.表决定，犹焉，如寡人愿有言～”；b.表比拟，犹言一般，如如见其肺肝～”）。\n(5)用于词尾，表示状态显～■～。飘飘～。\n(6)古同燃”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-然"},{"id":"glyph-seal-7145","script":"seal","character":"煅","reading":"duàn","description":"duàn：(1)同锻”。\n(2)放在火里烧，减少药石的烈性（中药的一种制法）～石膏。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-煅"},{"id":"glyph-seal-714c","script":"seal","character":"煌","reading":"huáng","description":"huáng：光明，明亮辉～。星火～～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-煌"},{"id":"glyph-seal-714e","script":"seal","character":"煎","reading":"jiān","description":"jiān：(1)熬～药。～熬。\n(2)烹饪方法，把食物放在少量的热油里弄熟～鱼。\n(3)量词，指中药煎汁的次数头～。二～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-煎"},{"id":"glyph-seal-715c","script":"seal","character":"煜","reading":"yù","description":"yù：(1)照耀日以～乎昼，月以～乎夜”。\n(2)火焰飞烽戢～而泱漭”。～熠。\n〔～～〕明亮的样子，如岭上疏星明～～”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-煜"},{"id":"glyph-seal-7166","script":"seal","character":"煦","reading":"xù","description":"xù：(1)温暖春风和～。～妪（抚养，天地生养万物）。～暖。温～。\n(2)恩惠～～为仁。\n(3)日出。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-煦"},{"id":"glyph-seal-7167","script":"seal","character":"照","reading":"zhào","description":"zhào：(1)光线射在物体上日～。～耀。～射。\n(2)对着镜子或其他反光的东西看自己或其他人物的影像～镜子。\n(3)摄影～相。拍～。\n(4)画像或相片小～。写～。\n(5)看顾～管。～顾。\n(6)按着，依着依～。遵～。～搬。～本宣科。\n(7)凭证护～。牌～。执～。\n(8)知晓心～不宣。肝胆相～。\n(9)通知，通告知～。～会。\n(10)对着，向着～壁。～敌人开枪。\n(11)查对对～。查～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-照"},{"id":"glyph-seal-7168","script":"seal","character":"煨","reading":"wēi","description":"wēi：(1)在带火的灰里烧熟东西～白薯。\n(2)用微火慢慢地煮～牛肉。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-煨"},{"id":"glyph-seal-716e","script":"seal","character":"煮","reading":"zhǔ","description":"zhǔ：把东西放在水里，用火把水烧开烹～。～饭。～字（喻书生玩味文字）。～豆燃箕（喻骨肉相残）。～鹤焚琴（喻大煞风景的事）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-煮"},{"id":"glyph-seal-717d","script":"seal","character":"煽","reading":"shān","description":"shān：同扇2”②。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-煽"},{"id":"glyph-seal-7184","script":"seal","character":"熄","reading":"xī","description":"xī：火灭，灭火～灭。～火。～灯。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-熄"},{"id":"glyph-seal-718a","script":"seal","character":"熊","reading":"xióng","description":"xióng：(1)哺乳动物，体大，尾短，四肢短而粗，脚掌大，能直立行走，也能攀树，种类很多，有棕熊”、白熊”、黑熊”等狗～（即黑熊”）。～掌。～白（熊背上的脂肪，白色，珍贵食品）。～胆（熊的胆，可入药）。～包（喻无能的人，废物）。\n(2)方言，指斥责挨了一顿～。\n(3)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-熊"},{"id":"glyph-seal-718f","script":"seal","character":"熏","reading":"xūn；xùn","description":"xūn：(1)气味或烟气接触物品，引申为长期接触的人或事物对品行、习惯的影响～染。～陶。～制。利欲～心。\n(2)火烟上出～蒸。\n(3)气味刺激人臭气～人。\n(4)暖和～风。\nxùn：（煤气）使人窒息中毒。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-熏"},{"id":"glyph-seal-7194","script":"seal","character":"熔","reading":"róng","description":"róng：固体受热到一定温度时变成液体～化。～点。～炉。～铸。～解。～岩。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-熔"},{"id":"glyph-seal-7199","script":"seal","character":"熙","reading":"xī","description":"xī：(1)光明。\n(2)兴起，兴盛。\n(3)和乐～怡。～笑。\n(4)古同禧”，福，吉祥。\n(5)古同嬉”，嬉戏。\n〔～～攘攘〕形容人来人往、喧闹纷杂的样子。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-熙"},{"id":"glyph-seal-719c","script":"seal","character":"熜","reading":"zǒng；cōng","description":"熜cōng 1.烟囱。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-熜"},{"id":"glyph-seal-71a0","script":"seal","character":"熠","reading":"yì","description":"yì：光耀，鲜明～～。～耀。～煜。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-熠"},{"id":"glyph-seal-71ac","script":"seal","character":"熬","reading":"áo；āo","description":"āo：烹调方法，把蔬菜等放在水里煮～白菜。\náo：(1)久煮～粥。～药。\n(2)忍受，耐苦支持煎～。～夜。～炼。\n(3)古同嗷”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-熬"},{"id":"glyph-seal-71b9","script":"seal","character":"熹","reading":"xī","description":"xī：(1)光明～微（日光微明）。星～。\n(2)炙，炽热东暾淡未～，北吹寒更寂”。\n(3)古人名用字。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-熹"},{"id":"glyph-seal-71ce","script":"seal","character":"燎","reading":"liáo；liǎo","description":"liáo：(1)延烧～荒。～原烈火。\n(2)烫～泡。\n(3)照明。\nliǎo：挨近火而烧焦把头发～了。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-燎"},{"id":"glyph-seal-71d4","script":"seal","character":"燔","reading":"fán","description":"fán：(1)焚烧～诗书而明法度”。\n(2)烤肉使熟～肉。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-燔"},{"id":"glyph-seal-71d5","script":"seal","character":"燕","reading":"yàn；yān","description":"yàn：(1)鸟类的一科，候鸟，常在人家屋内或屋檐下用泥做巢居住，捕食昆虫，对农作物有益～尔（形容新婚夫妇亲睦和美的样子）。～好（常用以指男女相爱）。～侣。～雀处（chǔ）堂（喻居安而不知远虑，临祸却不能自知）。\n(2)轻慢～朋逆其师”。\n(3)古同宴”，安闲，安乐。\n(4)古同宴”，宴饮。\nyān：(1)中国周代诸侯国名，在今河北省北部和辽宁省南部～赵。～山。～京。\n(2)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-燕"},{"id":"glyph-seal-71e0","script":"seal","character":"燠","reading":"yù","description":"yù：暧，热～热（闷热）‘～失时。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-燠"},{"id":"glyph-seal-71e5","script":"seal","character":"燥","reading":"zào","description":"zào：干，缺少水分干～。～裂。～热。枯～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-燥"},{"id":"glyph-seal-71ee","script":"seal","character":"燮","reading":"xiè","description":"xiè：谐和，调和～理。调（tiáo）～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-燮"},{"id":"glyph-seal-71f9","script":"seal","character":"燹","reading":"xiǎn","description":"xiǎn：野火。多指兵乱中纵火焚烧兵～。烽～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-燹"},{"id":"glyph-seal-7206","script":"seal","character":"爆","reading":"bào","description":"bào：(1)猛然炸裂并发出响声～豆。～花。～竹。～炸。～破。～裂。\n(2)出人意料地出现或发生～发。～满。～冷门。\n(3)烹调方法，快速油烹～鸡丁。\n(4)鼓出来眼睛～出。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-爆"},{"id":"glyph-seal-721d","script":"seal","character":"爝","reading":"jué","description":"jué：火把，小火～火。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-爝"},{"id":"glyph-seal-7228","script":"seal","character":"爨","reading":"cuàn","description":"cuàn：(1)烧火做饭分居各～。\n(2)灶客传萧寒～不烟。”\n(3)中国宋杂剧、金院本中某些简短表演的名称《讲百花～》。《文房四宝～》。\n(4)演戏夫优伶～演，实始有唐《目连救母》之起。”\n(5)姓。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-爨"},{"id":"glyph-seal-722a","script":"seal","character":"爪","reading":"zhǎo；zhuǎ","description":"zhǎo：(1)指甲或趾甲趾端有～。\n(2)鸟兽的脚指鹰～。～牙（喻党羽，狗腿子）。一鳞半～。\n(3)抓。\nzhuǎ：(1)禽兽的脚（多指有尖甲的）鸡～子。狗～子。\n(2)像爪的东西，这个锅有三个～儿。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-爪"},{"id":"glyph-seal-7230","script":"seal","character":"爰","reading":"yuán","description":"yuán：(1)于是～书其事以告。\n(2)改易，更换～田。\n(3)曰，为（wéi）水曰润下，火曰炎上，木曰曲直，金曰从革，土～稼穑”。\n(4)古代的一种重量单位或货币单位。\n(5)姓。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-爰"},{"id":"glyph-seal-7231","script":"seal","character":"爱","reading":"ài","description":"对人或事物有深厚真挚的感情\n⒈对人或事物有真诚、深厚的感情～人民。～祖国。她～教育工作。\n⒉喜好～清洁。她～唱歌。\n⒊重视，保护～惜时间。～护公物。\n⒋容易喝冷水～生病。\n⒌特指男女间的感情～情。恩～夫妻。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-爱"},{"id":"glyph-seal-7235","script":"seal","character":"爵","reading":"jué","description":"jué：(1)古代饮酒的器皿，三足，以不同的形状显示使用者的身份。\n(2)君主国家贵族封号（中国古代分为公”、侯”、伯”、子”、男”五等）～位。官～。～禄（爵位和俸禄）。～士。\n(3)古同雀”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-爵"},{"id":"glyph-seal-7236","script":"seal","character":"父","reading":"fù；fǔ","description":"fù：(1)爸爸，母亲的丈夫～母。～辈。～子。～兄。\n(2)对男性长辈的称呼～老（一国或一乡的长者，亦指古代乡里中管理公共事物的人）。伯～。舅～。\n女；子；母；\nfǔ：(1)老年人田～。渔～。\n(2)同甫”①。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-父"},{"id":"glyph-seal-723b","script":"seal","character":"爻","reading":"yáo","description":"yáo：组成八卦中每一卦的长短横道～象（a.卦的形象；b.喻形迹、真相）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-爻"},{"id":"glyph-seal-723d","script":"seal","character":"爽","reading":"shuǎng","description":"shuǎng：(1)明朗，清亮～目。\n(2)轻松，利落清～。凉～。～口。\n(3)痛快，率（shuài）直～朗。～快。～利±～。直～。\n(4)差失，违背～信。～约（失约）×厘不～。屡试不～。\n(5)干脆，索性～性。\n(6)舒服～心。～意。～适。身体不～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-爽"},{"id":"glyph-seal-723f","script":"seal","character":"爿","reading":"pán","description":"pán：(1)劈开的成片的木柴。\n(2)量词，指商店、田地、工厂等一～商店。一～水田。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-爿"}];
